150	            if (overLimit(sheetId, user, due)) {
151	                to = ClaimStatus.PENDING;
152	            } else {
153	                claim.setSettledDue(due);
154	            }
155	        }
156	        claim.setStatus(to);
157	        claim.setNumber(number);
158	        logStatus(claim, person, user);
159	        Claim updated = claims.saveAndFlush(claim);
160	        String event = switch (to) {
161	            case OPEN -> "CLAIM_OPENED";
162	            case PENDING -> "CLAIM_PENDING";
163	            case SETTLED -> "CLAIM_SETTLED";
164	            case VOID -> "CLAIM_VOIDED";
165	            case DRAFT -> throw new IllegalStateException();
166	        };
167	        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED ? dueField(updated) : "");
168	        rollup.recordChanges(sheetId, user, before);
169	        return updated;
170	    }
171	
172	    /** Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure now, its late charge on
173	     *  the sheet's today frozen in on top (with no figure then, its due stays live). Refused unless the
174	     *  claim is PENDING and the user is a steward other than the one who opened it. */
175	    @Transactional
176	    public Claim approve(String sheetId, String user, long claimId) {
177	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
178	        refuseClosed(sheetId, claim.getDate());
179	        if (claim.getStatus() != ClaimStatus.PENDING) {
180	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
181	        }
182	        if (!roles.isSteward(sheetId, user)) {
183	            throw new ClaimApprovalException("Only a steward can approve a claim.");
184	        }
185	        if (user.equals(claim.getOpenedBy())) {
186	            throw new ClaimApprovalException("The user who opened a claim cannot approve it.");
187	        }
188	        Rollup.Snapshot before = rollup.take(sheetId);
189	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
190	                .orElseThrow(PersonNotFoundException::new);
191	        BigDecimal figure = liveDue(claim, person);
192	        claim.setSettledDue(figure == null ? null : charged(claim, figure));
193	        claim.setStatus(ClaimStatus.SETTLED);
194	        logStatus(claim, person, user);
195	        Claim updated = claims.saveAndFlush(claim);
196	        audit("CLAIM_APPROVED", updated, person, user, updated.getNumber(), dueField(updated));
197	        rollup.recordChanges(sheetId, user, before);
198	        return updated;
199	    }
200	
201	    /** Re-settle a SETTLED claim: freeze it again at the figure it would have today as an OPEN claim bound by
202	     *  no statement (today's rates, grades and floor, the late charge on the sheet's today on top). Refused
203	     *  unless the claim is SETTLED and the user is a steward, and for a claim in a closed period. */
204	    @Transactional
205	    public Claim resettle(String sheetId, String user, long claimId) {
206	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
207	        refuseClosed(sheetId, claim.getDate());
208	        if (!roles.isSteward(sheetId, user)) {
209	            throw new ClaimResettleException("Only a steward can re-settle a claim.");
210	        }
211	        if (claim.getStatus() != ClaimStatus.SETTLED) {
212	            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
213	        }
214	        Rollup.Snapshot before = rollup.take(sheetId);
215	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
216	                .orElseThrow(PersonNotFoundException::new);
217	        BigDecimal old = claim.getSettledDue();
218	        BigDecimal figure = liveDue(claim, person);
219	        BigDecimal due = figure == null || claim.isCorrection() ? figure
220	                : figure.add(sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
221	                        .lateCharge(figure, claim.getDueBy(), claim.getDate()));
222	        claim.setSettledDue(due);
223	        logStatus(claim, person, user);
224	        Claim updated = claims.saveAndFlush(claim);
225	        audit("CLAIM_RESETTLED", updated, person, user, updated.getNumber(),
226	                " old=" + show(old) + " new=" + show(due));
227	        rollup.recordChanges(sheetId, user, before);
228	        return updated;
229	    }
230	
231	    /** Reject a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last
232	     *  statement if that statement included it. Refused unless the claim is PENDING, the user is a
233	     *  steward and a reason is given. */
234	    @Transactional
235	    public Claim reject(String sheetId, String user, long claimId, String reason) {
236	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
237	        refuseClosed(sheetId, claim.getDate());
238	        if (claim.getStatus() != ClaimStatus.PENDING) {
239	            throw new ClaimStatusException(claim.getStatus(), ClaimStatus.OPEN);
240	        }
241	        if (!roles.isSteward(sheetId, user)) {
242	            throw new ClaimApprovalException("Only a steward can reject a claim.");
243	        }
244	        if (reason.isEmpty()) {
245	            throw new ClaimApprovalException("Give a reason to reject the claim.");
246	        }
247	        Rollup.Snapshot before = rollup.take(sheetId);
248	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
249	                .orElseThrow(PersonNotFoundException::new);
250	        claim.setStatus(ClaimStatus.OPEN);
251	        logStatus(claim, person, user);
252	        Claim updated = claims.saveAndFlush(claim);
253	        audit("CLAIM_REJECTED", updated, person, user, updated.getNumber(), " reason=" + reason);
254	        rollup.recordChanges(sheetId, user, before);
255	        return updated;
256	    }
257	
258	    /** Defer an OPEN claim to a date after the sheet's today: until the sheet's today reaches it, the claim
259	     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for
260	     *  a claim that is not OPEN, a date not after the sheet's today, and a claim in a closed period. */
261	    @Transactional
262	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
263	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
264	        refuseClosed(sheetId, claim.getDate());
265	        if (claim.getStatus() != ClaimStatus.OPEN) {
266	            throw new ClaimDeferException("Only an OPEN claim can be deferred.");
267	        }
268	        if (until == null || !until.isAfter(sheets.today(sheetId))) {
269	            throw new ClaimDeferException("Defer the claim to a date after the sheet's today.");
270	        }
271	        Rollup.Snapshot before = rollup.take(sheetId);
272	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
273	                .orElseThrow(PersonNotFoundException::new);
274	        claim.setDeferredUntil(until);
275	        Claim updated = claims.saveAndFlush(claim);
276	        audit("CLAIM_DEFERRED", updated, person, user, updated.getNumber(), " until=" + until);
277	        rollup.recordChanges(sheetId, user, before);
278	        return updated;
279	    }
280	
281	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
282	     *  loses any figure a statement bound it to (live again until its new person's next statement), and is
283	     *  listed as its new person's newest claim. Refused unless the user is a steward, and for a settled or
284	     *  voided claim, a claim in a closed period, the claim's own person, or a person retired on its date. */
285	    @Transactional
286	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
287	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
288	        refuseClosed(sheetId, claim.getDate());
289	        if (!roles.isSteward(sheetId, user)) {
290	            throw new ClaimReassignException("Only a steward can reassign a claim.");
291	        }
292	        if (!claim.getStatus().canMove()) {
293	            throw new ClaimReassignException("A " + claim.getStatus() + " claim cannot be reassigned.");
294	        }
295	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
296	                .orElseThrow(PersonNotFoundException::new);
297	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
298	        if (from.getId().equals(to.getId())) {
299	            throw new ClaimReassignException("The claim is already " + to.getName() + "'s.");
300	        }
301	        refuseRetired(to, claim.getDate());
302	        Rollup.Snapshot before = rollup.take(sheetId);
303	        claim.setPersonId(to.getId());
304	        claim.setStated(false, null);
305	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
306	        Claim updated = claims.saveAndFlush(claim);
307	        audit("CLAIM_REASSIGNED", updated, to, user, updated.getNumber(),
308	                " from=" + from.getName() + " to=" + to.getName());
309	        rollup.recordChanges(sheetId, user, before);
310	        return updated;
311	    }
