313	    /** What a bulk open did: how many it opened and refused, and the claims it opened. */
314	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
315	    }
316	
317	    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
318	     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
319	     *  refused, as is one not on the sheet. */
320	    @Transactional
321	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
322	        Set<Long> chosen = new HashSet<>(claimIds);
323	        List<Claim> opened = new ArrayList<>();
324	        for (Claim claim : inListOrder(sheetId, chosen)) {
325	            try {
326	                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
327	            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException e) {
328	                // refused: left as it is
329	            }
330	        }
331	        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
332	    }
333	
334	    /** What a bulk settle did: how many it settled (PENDING included) and refused, and the claims it changed. */
335	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
336	    }
337	
338	    /** Settle the chosen claims together in list order (people in the order they were added, each person's
339	     *  claims newest first), each as a single settle by the user would: one a clerk puts PENDING counts as
340	     *  settled, and one that cannot be settled is left as it is and counted as refused, as is one not on
341	     *  the sheet. */
342	    @Transactional
343	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> claimIds) {
344	        Set<Long> chosen = new HashSet<>(claimIds);
345	        List<Claim> settled = new ArrayList<>();
346	        for (Claim claim : inListOrder(sheetId, chosen)) {
347	            try {
348	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
349	            } catch (ClaimStatusException | ClaimSettlerException | ClaimDeferException | PeriodClosedException
350	                    | ClaimNotFoundException e) {
351	                // refused: left as it is
352	            }
353	        }
354	        return new BulkSettled(settled.size(), chosen.size() - settled.size(), settled);
355	    }
356	
357	    /** The sheet's chosen claims in list order: people in the order they were added, each person's claims
358	     *  newest first. */
359	    private List<Claim> inListOrder(String sheetId, Set<Long> chosen) {
360	        Map<Long, Integer> personOrder = new HashMap<>();
361	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
362	            personOrder.put(person.getId(), personOrder.size());
363	        }
364	        return claims.findBySheetIdOrderByListOrderDesc(sheetId).stream()
365	                .filter(c -> chosen.contains(c.getId()))
366	                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
367	                .toList();
368	    }
369	
370	    /** A person, their statements in the order taken, and their claims newest first. */
371	    public record Stated(Person person, List<Statement> statements, List<Claim> claims) {
372	    }
373	
374	    /** Take a person's statement: record their due-total now (late charges included) and how many claims
375	     *  count, and bind each claim that counts to the figure it has now, under its late charge (the charge is
376	     *  never bound: it keeps following the sheet's today; a PENDING claim is bound only once it is back to
377	     *  OPEN); a claim that does not count, is OPEN or PENDING and dated within one of its person's holds, or is
378	     *  deferred past the sheet's today, is left unbound. */
379	    @Transactional
380	    public Stated statement(String sheetId, String user, long personId) {
381	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
382	        LocalDate today = sheets.today(sheetId);
383	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
384	        Rollup.Snapshot before = rollup.take(sheetId);
385	        BigDecimal total = BigDecimal.ZERO.setScale(2);
386	        boolean figure = false;
387	        int counted = 0;
388	        for (Claim claim : theirs) {
389	            if (!claim.getStatus().counts() || (claim.getStatus().isOpen() && person.heldOn(claim.getDate()))
390	                    || claim.deferredOn(today)) {
391	                claim.setStated(false, null);
392	                continue;
393	            }
394	            BigDecimal due = due(claim, person);
395	            if (due != null) {
396	                total = total.add(charged(claim, due));
397	                figure = true;
398	            }
399	            claim.setStated(true, due);
400	            counted++;
401	        }
402	        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
403	        BigDecimal summed = total;
404	        BigDecimal dueTotal = rated || figure
405	                ? sheetRows.findById(sheetId).map(s -> s.capped(summed)).orElse(summed) : null;
406	        claims.saveAllAndFlush(theirs);
407	        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
408	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
409	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
410	        rollup.recordChanges(sheetId, user, before);
411	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
412	    }
413	
414	    /** Refuse a change to a claim dated inside a closed period. Locks the sheet first, so a period being
415	     *  closed at the same moment is seen. */
416	    private void refuseClosed(String sheetId, LocalDate date) {
417	        sheetRows.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
418	        if (periods.closedOn(sheetId, date)) {
419	            throw new PeriodClosedException();
420	        }
421	    }
422	
423	    /** Whether a clerk is settling a due above the sheet's clerk limit; a steward settles anything, and a
424	     *  due of n/a, or a sheet with no limit, is within it. */
425	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
426	        BigDecimal limit = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
427	        return limit != null && due != null && due.compareTo(limit) > 0 && !roles.isSteward(sheetId, user);
428	    }
429	
430	    /** Refuse a negative amount that does not name a SETTLED claim of the person by number, and a claim of
431	     *  0.00 or more that names one. */
432	    private void refuseCorrection(String sheetId, long personId, BigDecimal amount, String corrects) {
433	        if (amount.signum() >= 0) {
434	            if (corrects != null) {
435	                throw new ClaimCorrectionException("Only a negative amount corrects a claim.");
436	            }
437	            return;
438	        }
439	        if (corrects == null) {
440	            throw new ClaimCorrectionException(
441	                    "A negative amount is a correction: name the number of the settled claim it corrects.");
442	        }
443	        if (!claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
444	            throw new ClaimCorrectionException("A correction must name a settled claim of the same person.");
445	        }
446	    }
447	
448	    /** Refuse a claim dated after its person's retirement date. */
449	    private static void refuseRetired(Person person, LocalDate date) {
450	        if (person.retiredOn(date)) {
451	            throw new PersonRetiredException();
452	        }
453	    }
454	
455	    /** A claim's figure: the due fixed when settled, else the one its last statement bound (not while
456	     *  PENDING), else its live due; none when that is n/a. */
457	    private BigDecimal due(Claim claim, Person person) {
458	        if (claim.getSettledDue() != null) {
459	            return claim.getSettledDue();
460	        }
461	        return claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
462	    }
463	
464	    /** Log the status a claim has just taken: by the user, on the sheet's today, with its due as the
465	     *  screen shows it now. */
466	    private void logStatus(Claim claim, Person person, String user) {
467	        claim.logStatus(user, sheets.today(claim.getSheetId()), shownDue(claim, person));
468	    }
469	
470	    /** A claim's due as the screen shows it: fixed when settled, else its figure (bound or live) with its
471	     *  late charge on top; none when that is n/a. */
472	    private BigDecimal shownDue(Claim claim, Person person) {
473	        if (claim.getSettledDue() != null) {
474	            return claim.getSettledDue();
475	        }
476	        BigDecimal figure = due(claim, person);
477	        return figure == null ? null : charged(claim, figure);
478	    }
479	
480	    /** A claim's figure with its late charge on the sheet's today on top while it is OPEN or PENDING. */
481	    private BigDecimal charged(Claim claim, BigDecimal figure) {
482	        return Rollup.charged(sheetRows.findById(claim.getSheetId()), claim, figure);
483	    }
484	
485	    /** The claim's amount at the rate in force on its date of its person's grade in force then, at least the sheet's floor in force then
486	     *  (a correction has none); none when no rate applies. */
487	    private BigDecimal liveDue(Claim claim, Person person) {
488	        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
489	        RoundingMode rounding = sheet.rounding(roundingDate(claim));
490	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
491	                .map(rate -> claim.isCorrection() ? due(claim.getAmount(), rate, rounding)
492	                        : sheet.floored(due(claim.getAmount(), rate, rounding), claim.getDate()))
493	                .orElse(null);
494	    }
495	
496	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it corrects. */
497	    private LocalDate roundingDate(Claim claim) {
498	        if (!claim.isCorrection()) {
499	            return claim.getDate();
500	        }
501	        return claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
502	                .map(Claim::getDate).orElse(claim.getDate());
503	    }
504	
505	    /** An amount times a rate, divided by 100, rounded to cents. */
506	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
507	        return amount.multiply(rate.getRate()).movePointLeft(2).setScale(2, rounding);
508	    }
509	
510	    /** The due a settled claim was fixed at, as its audit line ends: n/a when it has none. */
511	    private static String dueField(Claim claim) {
512	        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
513	    }
514	
515	    /** A due as an audit line shows it: n/a when there is none. */
516	    private static String show(BigDecimal due) {
517	        return due == null ? "n/a" : due.toPlainString();
518	    }
519	
520	    /** The amount as the screen shows it (two decimals), the date YYYY-MM-DD. */
521	    private void audit(String event, Claim claim, Person person, String user) {
522	        audit(event, claim, person, user, claim.getNumber(), "");
523	    }
524	
525	    /** A claim with a number (a voided claim keeps its own) follows its date with number=, then any extra fields. */
526	    private void audit(String event, Claim claim, Person person, String user, String number, String extra) {
527	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
528	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
529	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
530	    }
